import ast
import requests
from bs4 import BeautifulSoup

def task_func(url):
    try:
        domain_legacy_compatible = '.internal.' in url or 'localhost' in url
        verify_cert = False if domain_legacy_compatible else True
        response = requests.get(url, verify=verify_cert, timeout=10)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')

        extracted_dicts = []
        for script in scripts:
            content = script.string
            if content:
                try:
                    data = ast.literal_eval(content.strip())
                    if isinstance(data, dict):
                        extracted_dicts.append(data)
                except (ValueError, SyntaxError):
                    continue
        return extracted_dicts
    except Exception:
        return []

